#!/usr/bin/env python3
from __future__ import annotations
import pathlib, sys
ROOT=pathlib.Path(__file__).resolve().parents[1]
def text(p): return (ROOT/p).read_text()
checks=[]
def check(n,c): checks.append((n,c))
cargo=text('Cargo.toml'); core=text('crates/sparkbridge-core/src/lib.rs'); protocol=text('crates/sparkbridge-protocol/src/lib.rs')
task=text('crates/sparkbridge-task/src/lib.rs'); agent=text('crates/sparkbridge-agent/src/lib.rs')
server=text('apps/sparkbridge-server/src/main.rs'); runtime=text('apps/sparkbridge-server/src/agent_runtime.rs'); store=text('apps/sparkbridge-server/src/store.rs')
executor=text('apps/sparkbridge-executor/src/main.rs'); execution=text('crates/sparkbridge-execution/src/lib.rs'); cli=text('apps/sparkbridge-cli/src/main.rs'); config=text('crates/sparkbridge-config/src/lib.rs')
check('workspace version 0.12.0','version = "0.12.0"' in cargo)
check('protocol is 1.10','PROTOCOL_MINOR: u16 = 10' in protocol)
check('schema is v9','SCHEMA_VERSION: u32 = 9' in store and 'PRAGMA user_version = 9' in store)
check('task and agent crates are workspace members','crates/sparkbridge-task' in cargo and 'crates/sparkbridge-agent' in cargo)
check('iteration 7 features negotiate','ITERATION_7_AGENT' in core and all(x in core for x in ['DeterministicAgentRuntime','TaskEventLog','CandidateValidationSandbox']))
check('TaskSpec has objective/workspace/base/model',all(x in task for x in ['pub objective: String','pub workspace_id: String','pub base_snapshot_id: String','pub model: String']))
check('task budgets cover wall/model/action/candidate/repair',all(x in task for x in ['max_wall_time_ms','max_model_calls','max_actions','max_candidates','max_repair_cycles']))
check('task status is explicit',all(x in task for x in ['Created','Running','WaitingForAction','Paused','Completed','BudgetExceeded']))
check('task counters are durable',all(x in task for x in ['model_calls','actions','candidates','repair_cycles']))
check('task events are immutable typed objects','pub struct TaskEvent' in task and 'pub enum TaskEventKind' in task)
check('events persist with sequence uniqueness','CREATE TABLE IF NOT EXISTS task_events' in store and 'UNIQUE(task_id, sequence)' in store)
check('task projection is persisted','CREATE TABLE IF NOT EXISTS tasks' in store and 'record_json' in store)
check('task events carry replayable projections','"projection": record' in store and 'replay_task_projection' in store)
check('task/event projection writes are transactional','transaction.execute' in store and 'insert_task_event(&transaction' in store and 'transaction.commit()' in store)
check('server recovers tasks on startup','recover_tasks' in server and 'Recovered' in store)
check('orphaned task actions can be reattached','origin_task_id' in protocol and 'reattached orphaned validation action' in store)
check('one runtime loop per task is serialized','task_locks' in server and 'task_lock.lock().await' in server)
check('context bundles are content addressed','ContextBundle' in task and 'last_context_digest' in task and 'state.cas.put_bytes' in runtime)
check('context has bounded total and file sizes','agent_context_max_bytes' in config and 'agent_context_file_max_bytes' in config)
check('explicit source context remains first priority','context_paths' in task and 'task.spec.context_paths.iter()' in runtime and 'candidate_paths.iter()' in runtime and 'ranked_paths.iter()' in runtime)
check('diagnostic source files join repair context','evidence_paths' in task and 'result.diagnostics' in runtime and 'requested_paths.push' in runtime)
check('diagnostic paths normalize to workspace relative','normalize_diagnostic_paths' in execution and 'strip_prefix(&canonical_root)' in execution)
check('agent output is structured JSON directives','pub enum AgentDirective' in task and 'parse_directive' in agent and 'format": "json"' in text('apps/sparkbridge-server/src/inference.rs'))
check('model cannot invent validation commands','validation commands are controlled by TaskSpec' in agent and 'validation_actions' in task)
check('model call is durable before inference','TaskEventKind::ModelRequested' in runtime and 'agent_chat_json' in runtime)
check('invalid model directives pause task','invalid model directive' in runtime and 'TaskStatus::Paused' in runtime)
check('inference failure pauses instead of losing task','inference temporarily unavailable' in runtime and 'TaskEventKind::TaskPaused' in runtime)
check('candidate rejection feeds repair evidence','CandidateRejected' in task and 'candidate rejected by deterministic validator' in runtime)
check('candidate delta remains anchored to base snapshot','base_snapshot_id: task.spec.base_snapshot_id.clone()' in runtime and 'complete desired delta against the immutable BASE snapshot' in agent)
check('candidate validation actions are pure','side_effect: ActionSideEffect::Pure' in runtime)
check('candidate validation actions carry candidate ID','candidate_id: Some(candidate_id.clone())' in runtime)
check('executor reconstructs candidate sandbox from CAS','prepare_action_workspace' in executor and 'materialize_candidate_sandbox' in executor and 'fetch_cas_object' in executor)
check('candidate sandbox is disposable','disposable: true' in executor and 'remove_dir_all(&prepared.path)' in executor)
check('stale candidate sandboxes are cleaned at startup','cleanup_action_sandboxes' in executor)
check('candidate validation is workspace-bound and cross-node safe','candidate workspace does not match action workspace' in executor and 'same logical workspace' in executor and 'promotion' in executor)
check('sandbox symlinks cannot escape workspace','candidate sandbox symlink escapes workspace' in executor and 'refuses absolute symlink target' in executor)
check('Windows symlink limitation is explicit','candidate sandbox containing symlinks is not supported on Windows' in executor)
check('validation result feeds deterministic repair cycle','ActionObserved' in runtime and 'repair_cycles' in runtime and 'last_evidence' in runtime)
check('multiple validation actions advance in order','validation_index' in task and 'validation_index.saturating_add(1)' in runtime)
check('completion can require candidate and validation','require_candidate' in task and 'require_validation' in task and 'completion rejected' in runtime)
check('task pause/resume/cancel APIs exist',all(x in server for x in ['/pause','/resume','admin_cancel_task']))
check('task CLI supports lifecycle',all(x in cli for x in ['TasksCommand::Create','TasksCommand::Run','TasksCommand::Events','TasksCommand::Pause','TasksCommand::Resume','TasksCommand::Cancel']))
check('follow mode polls durable task loop','follow' in cli and 'tokio::time::sleep' in cli and 'run.task.status.terminal()' in cli)
check('task cancellation propagates to pending action','cancel_action(action_id' in server)
check('agent actions remain under executor allowlist','action_allowed_commands' in config and 'is not allowed by executor policy' in execution)
check('agent does not auto-promote candidates','TransactionalPromotion' in core and 'promote_candidate' not in runtime)
failed=[n for n,c in checks if not c]
for n,c in checks: print(('PASS' if c else 'FAIL')+': '+n)
if failed:
 print(f'\n{len(failed)} agent invariant(s) failed',file=sys.stderr); sys.exit(1)
print(f'\nDeterministic Agent Runtime audit passed: {len(checks)} invariants')
